#!/bin/bash
# EVAL-011: output readability after stripping non-ASCII; an agent parses status words. Persona c.
source "$(dirname "$0")/lib.sh"
start_log EVAL-011-ascii-status-words.log "EVAL-011 report statuses survive stripping non-ASCII and are parseable words"
T=$(new_repo eval-011); cd "$T"
printf '# Acme\n' > AGENTS.md; printf 'x\n' > app.rb
run git add -A; run git commit -q -m "Project files"
note "STEP 1: run producing created, updated, skipped: capture raw bytes to a file"
runsh "$SF init --no-onboard > $SCRATCH/eval-011-run1.raw 2>&1; echo exit=\$?"
run git add -A; run git commit -q -m "Adopt"
runsh "printf '\nlocal edit\n' >> .ai/rules/git.md; git add -A; git commit -q -m 'Edit rule'; echo committed"
note "STEP 2: run producing conflict (committed edit, canonical unchanged so init sees manifest mismatch): capture raw bytes"
runsh "$SF init --no-onboard > $SCRATCH/eval-011-run2.raw 2>&1; echo exit=\$?"
note "STEP 3: run producing forced"
runsh "$SF init --force --no-onboard > $SCRATCH/eval-011-run3.raw 2>&1; echo exit=\$?"
note "STEP 4: byte analysis of the raw outputs"
runsh "for f in $SCRATCH/eval-011-run1.raw $SCRATCH/eval-011-run2.raw $SCRATCH/eval-011-run3.raw; do printf '%s: bytes=%s non-ascii-bytes=%s\n' \$(basename \$f) \$(wc -c < \$f) \$(LC_ALL=C tr -d '\\000-\\177' < \$f | wc -c); done"
note "STEP 5: strip non-ASCII (LC_ALL=C tr -cd) and parse status words with awk as an agent would"
runsh "for f in $SCRATCH/eval-011-run1.raw $SCRATCH/eval-011-run2.raw $SCRATCH/eval-011-run3.raw; do echo \"== \$(basename \$f)\"; LC_ALL=C tr -cd '\\011\\012\\040-\\176' < \$f | awk '\$1 ~ /^(created|updated|skipped|conflict|forced)\$/ {c[\$1]++} /^summary:/ {print \"summary line: \" \$0} END {for (k in c) printf \"parsed %s %d\\n\", k, c[k]}' | sort; done"
note "STEP 6: the parsed counts must equal the summary counts"
runsh "for f in $SCRATCH/eval-011-run1.raw $SCRATCH/eval-011-run2.raw $SCRATCH/eval-011-run3.raw; do LC_ALL=C tr -cd '\\011\\012\\040-\\176' < \$f | awk '\$1 ~ /^(created|updated|skipped|conflict|forced)\$/ {c[\$1]++} /^summary:/ {s=\$0} END {gsub(/^summary: /,\"\",s); n=split(s,parts,\", \"); ok=1; for(i=1;i<=n;i++){split(parts[i],kv,\" \"); if (c[kv[1]]+0 != kv[2]+0) {ok=0; printf \"MISMATCH %s parsed=%d summary=%d\\n\", kv[1], c[kv[1]], kv[2]}} print (ok ? \"counts consistent\" : \"counts inconsistent\")}'; done"
note "STEP 7: lines that carry a reason keep it in parentheses after two spaces"
runsh "LC_ALL=C tr -cd '\\011\\012\\040-\\176' < $SCRATCH/eval-011-run2.raw | grep -E '^(conflict|updated|skipped) ' | grep '(' | head -4"
CONSISTENT=$(sed -n '/STEP 6/,/STEP 7/p' "$LOG" | grep -c '^counts consistent')
note "ASSERTIONS"
assert "AC-016 raw outputs contain no non-ASCII bytes" "! sed -n '/STEP 4/,/STEP 5/p' '$LOG' | grep -Eq 'non-ascii-bytes=[1-9]'"
assert "AC-016 created/updated/skipped parsed after stripping (run 1)" "sed -n '/STEP 5/,/STEP 6/p' '$LOG' | sed -n '/run1/,/run2/p' | grep -q 'parsed created' && sed -n '/STEP 5/,/STEP 6/p' '$LOG' | sed -n '/run1/,/run2/p' | grep -q 'parsed updated'"
assert "AC-016 conflict parsed after stripping (run 2)" "sed -n '/STEP 5/,/STEP 6/p' '$LOG' | sed -n '/run2/,/run3/p' | grep -q 'parsed conflict 1'"
assert "AC-016 forced parsed after stripping (run 3)" "sed -n '/STEP 5/,/STEP 6/p' '$LOG' | sed -n '/run3/,\$p' | grep -q 'parsed forced 1'"
assert "AC-016 parsed counts equal summary counts in all three runs" "[ $CONSISTENT -eq 3 ]"
assert "exit codes 0, 3, 0 across the three runs" "sed -n '/STEP 1/,/STEP 2/p' '$LOG' | grep -q '^exit=0' && sed -n '/STEP 2/,/STEP 3/p' '$LOG' | grep -q '^exit=3' && sed -n '/STEP 3/,/STEP 4/p' '$LOG' | grep -q '^exit=0'"
finish EVAL-011
